mapper.select:
SELECT pr.id, pr.persona_id, pr.usuario_id, pr.latitud, pr.longitud, pr.radio_cobertura_km, pr.descripcion, pr.verificado, pr.calificacion, pr.created_at, pr.updated_at, pr.deleted, pr.version FROM petcare.proveedor pr LEFT JOIN petcare.persona p ON p.id = pr.persona_id AND p.deleted = FALSE
pr.deleted = FALSE AND (p.nombre ILIKE '%' || #{nombre} '%' OR p.primer_apellido ILIKE '%' || #{nombre} '%')
ORDER BY pr.created_at DESC LIMIT #{limit} OFFSET #{offset}
